const FILES={"index.html":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#1d342c\"><title>Marginalia · Reading room</title><link rel=\"stylesheet\" href=\"/style.css\"><script src=\"/app.js\" defer></script></head><body><a class=\"skip\" href=\"#main\">Skip to content</a><header><div class=\"bar\"><a class=\"brand\" href=\"#home\"><span aria-hidden=\"true\">◧</span> Marginalia</a><nav aria-label=\"Main navigation\"><a href=\"#home\">Reading room</a><a href=\"#library\">Bookshelf</a><a href=\"#saved\">Saved</a><a href=\"#compare\">Compare</a></nav><button id=\"theme\">Theme</button><button id=\"account\">My account</button></div></header><main id=\"main\" tabindex=\"-1\"><p>Opening your reading room…</p></main><footer>Marginalia <span>Personal book companion</span><a href=\"/source.zip\" download>Download project</a></footer><div id=\"toast\" role=\"status\"></div><dialog id=\"dialog\"><button id=\"close\" aria-label=\"Close dialog\">Close</button><section id=\"modal\"></section></dialog></body></html>","app.js":"(function client(){\n'use strict';\nconst themeButton=document.getElementById('theme'), systemTheme=matchMedia('(prefers-color-scheme: dark)');\nfunction paintTheme(){const dark=(localStorage.getItem('reading-theme') || (systemTheme.matches?'dark':'light'))==='dark';document.documentElement.dataset.theme=dark?'dark':'light';themeButton.textContent=dark?'Light mode':'Dark mode'}\nthemeButton.onclick=()=>{localStorage.setItem('reading-theme',document.documentElement.dataset.theme==='dark'?'light':'dark');paintTheme()};systemTheme.addEventListener('change',paintTheme);paintTheme();\nlet books=[],state={},minutes=2,topic='All',noticeTimer,dialog=document.querySelector('#dialog'),main=document.querySelector('main');const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c])),colors=['#a4563c','#536356','#53618d','#946128','#834b63','#426d70'],by=id=>books.find(b=>b.id===Number(id)),href=(b,i=0,m=minutes)=>'#read/'+b.id+'/'+i+'/'+m,blank=()=>({account:false,marks:[],progress:null}),guest=()=>{try{return JSON.parse(localStorage.getItem('marginalia-v1'))||blank()}catch{return blank()}},saveLocal=()=>localStorage.setItem('marginalia-v1',JSON.stringify(state));\nasync function api(path,data){const r=await fetch('/api/'+path,data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{});const v=await r.json();if(!r.ok)throw Error(v.error||'Unable to save. Try again.');return v}\nasync function sync(){let x=await api('state');state=x.account?x:guest();books=await api('catalog');$('#account').textContent=state.account?'My library key':'My account'}\nfunction toast(s){clearTimeout(noticeTimer);$('#toast').textContent=s;noticeTimer=setTimeout(()=>$('#toast').textContent='',3000)}\nfunction jacket(b){return `<div aria-hidden=\"true\" class=\"jacket\" style=\"--cover:${colors[b.id%colors.length]}\"><strong>${esc(b.title)}</strong><small>${esc(b.author.split(',')[0])}</small></div>`}\nfunction card(b){return `<a class=\"book\" href=\"${href(b)}\">${jacket(b)}<div><small>${esc(b.topic)}</small><h3>${esc(b.title)}</h3><small>${b.ideas.length} ideas</small></div></a>`}\nfunction marks(b,i){return state.marks.find(x=>x.book===b.id&&x.idea===i)||{}}\nfunction btn(k,v,label,active=false){return `<button data-act=\"${k}\" data-v=\"${esc(v)}\" aria-pressed=\"${active}\">${esc(label)}</button>`}\nconst modes=()=>`<div class=\"chips\" aria-label=\"Reading time\">${[2,5,15].map(n=>btn('minutes',n,n+' min',n===minutes)).join('')}</div>`;\nconst queries={'under pressure':'overthinking focus attention contest performance concentration','overthinking':'focus attention observation contest','should i quit':'persist cost tactic continuing goal abandon','stuck debugging':'practice feedback debug test','friend upset':'listen listening support friend communicate','trust the numbers':'data trend distribution rates facts','learn faster':'mentor practice skill feedback' };\nfunction matches(q){let words=q.toLowerCase().split(/\\W+/).filter(w=>w.length>2&&!['the','how','should','what','when','with','whether','can','why','and','for','you','about','does'].includes(w));for(const [k,v] of Object.entries(queries))if(q.toLowerCase().includes(k))words.push(...v.split(' '));let out=[];for(const b of books){if(topic!=='All'&&topic!==b.topic)continue;let best=-1,idx=0;for(const [i,t] of b.ideas.entries()){let score=words.reduce((s,w)=>s+(t.toLowerCase().includes(w)?5:0)+(b.title.toLowerCase().includes(w)?7:0)+((b.overview+' '+b.example+' '+b.topic+' '+b.author).toLowerCase().includes(w)?1:0),0);if(score>best){best=score;idx=i}}if(best>0||!q.trim())out.push({b,idx,best})}return out.sort((a,b)=>b.best-a.best)}\nfunction searchUI(){return `<label for=\"q\">Find advice for a question or situation</label><input class=\"query\" id=\"q\" type=\"search\" placeholder=\"Try “under pressure” or “should I quit?”\"><div class=\"chips\">${['All','Practice','Judgment','Mind','Relationships','Influence'].map(t=>btn('topic',t,t,topic===t)).join('')}</div><div id=\"results\"></div>`}\nfunction results(){const q=$('#q').value,rs=matches(q);$('#results').innerHTML=q?`<div class=\"stack\">${rs.map(({b,idx})=>`<a class=\"item\" href=\"${href(b,idx)}\"><small>${esc(b.title)}</small><h3>${esc(b.ideas[idx])}</h3></a>`).join('')||'<p>No matching ideas. Try “focus”, “feedback”, or another topic.</p>'}</div>`:`<div class=\"grid\">${rs.map(({b})=>card(b)).join('')}</div>`}\nfunction home(){const p=state.progress,b=by(p?.book)??books[0];main.innerHTML=`<section class=\"hero\"><div><div class=\"label\">${p?'Continue reading':'Start here'}</div><h1>${esc(b.title)}</h1><p>${esc(b.ideas[p?.idea||0]||b.ideas[0])}.</p><a class=\"btn\" href=\"${href(b,p?.idea||0,p?.minutes||minutes)}\">${p?'Resume reading':'Open the guide'}</a></div><div class=\"art\">${jacket(books[1]||b)}${jacket(b)}</div></section><section class=\"section\"><div class=\"heading\"><h2>Your bookshelf</h2><a href=\"#library\">All ${books.length} guides</a></div><div class=\"chips\"><a class=\"btn\" href=\"#read/0/1/5\">Contest pressure</a><a class=\"btn\" href=\"#read/0/0/5\">Stuck debugging</a><a class=\"btn\" href=\"#read/1/3/5\">Learning a skill</a><a class=\"btn\" href=\"#read/2/9/5\">Should I keep going?</a></div>${searchUI()}</section>`;results()}\nconst comparisons=[\n['Should I keep going or change direction?',2,4,'Grit asks whether a different tactic could serve an enduring interest. The Almanack asks what else the same time and energy could produce.','Write one cheap experiment, the evidence that would justify continuing, and the opportunity you give up while trying it.'],\n['How can I perform under pressure?',0,1,'Gallwey looks at the moment of execution. Greene looks at the months of practice that make an effective response available.','Choose one cue to use during your next contest and one weakness to practice afterward.'],\n['Is this chart telling the whole story?',3,5,'Factfulness asks which denominator, trend or comparison is missing. Roam asks which drawing makes the question easier to see.','Redraw one headline number as both a trend and a rate. Record what changes.'],\n['How should I respond to a tense conversation?',14,19,'Gray invites a check on the kind of support someone wants. Greene invites a check on the motives you may be projecting.','Ask one open question before deciding why the other person spoke as they did.']];\nfunction compare(){main.innerHTML=`<h1>Compare perspectives</h1><p>Read two approaches to the same decision.</p><div class=\"stack\">${comparisons.map(([q,a,b,s,t])=>`<article class=\"panel\"><h2>${esc(q)}</h2><p>${esc(s)}</p><div class=\"dual\">${[by(a),by(b)].filter(Boolean).map(card).join('')}</div><p style=\"margin-top:1rem\"><b>Try this.</b> ${esc(t)}</p></article>`).join('')}</div>`}\nfunction reader(b,i){const mark=marks(b,i),topicGuide=b.author.startsWith('Topic'),sourceLabel=[10,11].includes(b.id)?'Independent clinical guidance':b.source.includes('openlibrary')?'Find editions in Open Library':'Author or project resource';main.innerHTML=`<div class=\"shell\"><aside class=\"side\"><a href=\"#library\">Back to bookshelf</a><details ${innerWidth>800?'open':''}><summary>Contents · ${b.ideas.length} ideas</summary>${b.ideas.map((t,j)=>`<a href=\"${href(b,j)}\" ${i===j?'aria-current=\"step\"':''}>${j+1}. ${esc(t)}</a>`).join('')}</details></aside><article class=\"reader\"><div class=\"label\">${esc(b.topic)} · ${topicGuide?'Editorial topic guide':'Book guide'}</div><h1>${esc(b.title)}</h1><p class=\"muted\">${esc(b.author)}</p><p>${esc(b.overview)}</p>${modes()}<section class=\"idea\"><div class=\"label\">Idea ${i+1} of ${b.ideas.length}</div><h2>${esc(b.ideas[i])}</h2>${b.lessons?.[i]?`<p>${esc(b.lessons[i][0])}</p>`:\"\"}<div class=\"actions\">${btn('mark','saved',mark.saved?'Saved ✓':'Save idea',!!mark.saved)}${btn('mark','tried',mark.tried?'Tried ✓':'Mark as tried',!!mark.tried)}</div></section>${minutes>=5?`<section class=\"panel\"><h3>In practice</h3><p>${esc(b.cases?.[i] || b.example)}</p><p><b>Your turn.</b> ${esc(b.lessons?.[i]?.[1] || b.ideas[i]+'. Choose a real situation and record what you observe.')}</p></section>`:''}${minutes===15?`<section class=\"panel\"><h3>Explore the idea</h3><p>Spend five minutes on the exercise above. Compare the result with your prediction, then try the related idea with one change.</p><a href=\"${href(b,(i+1)%b.ideas.length,5)}\">Read the related idea</a><p><b>Consider the limits.</b> ${esc(b.limit)}</p><p><b>Connect two ideas.</b> How would your approach change if you also tried “${esc(b.ideas[(i+1)%b.ideas.length])}”?</p><p><b>Reflect.</b> Name a situation where this advice might fail. What would you need to know before acting?</p><a href=\"#compare\">Compare perspectives across books</a></section>`:''}<div class=\"heading\">${i?`<a class=\"btn\" href=\"${href(b,i-1)}\">Previous idea</a>`:'<span></span>'}${i<b.ideas.length-1?`<a class=\"btn primary\" href=\"${href(b,i+1)}\">Next idea</a>`:'<a class=\"btn primary\" href=\"#library\">Return to bookshelf</a>'}</div><details class=\"panel\"><summary>Sources and edition notes</summary><p><b>Reading-list entry.</b> ${esc(b.title)} · ${esc(b.author)}.</p><p>${topicGuide?'Edition unconfirmed. These prompts are an editorial introduction to the topic.':'Original study prompts inspired by '+esc(b.title)+' by '+esc(b.author)+'. Examples and exercises are editorial applications.'}</p><p>${esc(b.limit)}</p><a href=\"${esc(b.source)}\" target=\"_blank\" rel=\"noopener\">${sourceLabel}</a></details></article></div>`}\nlet seq=Promise.resolve();function persist(path,v){if(!state.account){saveLocal();return Promise.resolve()}const op=seq.catch(()=>{}).then(()=>api(path,v));seq=op;return op}\nfunction route(){const [page='home',id,index,m]=location.hash.slice(1).split('/');for(const a of document.querySelectorAll('nav a'))a.setAttribute('aria-current',a.hash==='#'+(page||'home')?'page':'false');if(page==='read'){const b=by(id),i=Number(index||0);if(!b||!Number.isInteger(i)||!b.ideas[i]){main.innerHTML='<h1>Guide unavailable</h1><a href=\"#library\">Open bookshelf</a>';return}minutes=[2,5,15].includes(+m)?+m:2;reader(b,i);const p={book:b.id,idea:i,minutes};state.progress=p;persist('progress',p).catch(e=>toast(e.message))}\nelse if(page==='library'){main.innerHTML=`<h1>Bookshelf</h1><p>${books.length} guides · ${books.reduce((n,b)=>n+b.ideas.length,0)} ideas</p>${searchUI()}`;results()}\nelse if(page==='saved'){main.innerHTML=`<h1>Your notebook</h1>${['saved','tried'].map(k=>`<section class=\"section\"><h2>${k==='saved'?'Saved ideas':'Ideas you’ve tried'}</h2><div class=\"stack\">${state.marks.filter(x=>x[k]&&by(x.book)).map(x=>{let b=by(x.book);return `<a class=\"item\" href=\"${href(b,x.idea)}\"><small>${esc(b.title)}</small><h3>${esc(b.ideas[x.idea])}</h3></a>`}).join('')||'<p>Open a guide and use the button on an idea to add it here.</p>'}</div></section>`).join('')}`}\nelse if(page==='compare')compare();else if(page==='admin'&&state.admin)admin();else home();document.title=($('#main h1')?.textContent||'Reading room')+' · Marginalia'}\nfunction admin(){main.innerHTML=`<h1>Edit guides</h1><label>Guide<select id=\"editBook\">${books.map(b=>`<option value=\"${b.id}\">${esc(b.title)}</option>`).join('')}</select></label><form id=\"editor\"></form>`;edit()}\nfunction edit(){let b=by($('#editBook').value);$('#editor').innerHTML=['title','author','overview','example','limit','ideas'].map(k=>`<label>${k}<textarea required name=\"${k}\" rows=\"${k==='ideas'?12:2}\">${esc(k==='ideas'?b.ideas.join('\\n'):b[k])}</textarea></label>`).join('')+`<label><select name=\"published\"><option value=\"true\">Published</option><option value=\"false\" ${b.published===false?'selected':''}>Draft</option></select></label><button>Save guide</button>`}\nfunction account(){if(!dialog.open)dialog.showModal();$('#modal').innerHTML=state.account?`<h2>Your account</h2><p>Your saved ideas and reading position sync when you use your reading key on another device.</p>${state.admin?'<a href=\"#admin\" id=\"adm\">Edit guides</a>':''}<button data-act=\"logout\">Sign out</button>`:`<h2>Your reading key</h2><p>Create a private key to carry your progress between laptop and phone. Keep it somewhere safe.</p><button class=\"primary\" data-act=\"create\">Create my reading key</button><form id=\"login\"><label>Already have a key?<input name=\"key\" required autocomplete=\"off\" type=\"password\"></label><button>Sign in</button></form>`}\nasync function enter(k){const g=guest();await sync();if(!k)return;for(const z of g.marks||[])for(const f of ['saved','tried'])if(z[f])await api('mark',{book:z.book,idea:z.idea,field:f,on:true});if(g.progress)await api('progress',g.progress);localStorage.removeItem('marginalia-v1');await sync()}\ndocument.addEventListener('input',e=>{if(e.target.id==='q')results()});document.addEventListener('change',e=>{if(e.target.id==='editBook')edit()});\ndocument.addEventListener('submit',async e=>{e.preventDefault();try{if(e.target.id==='login'){await api('login',{key:e.target.key.value});await enter(false);dialog.close();if(location.hash!=='#home')location.hash='#home';else route();toast('Signed in')}if(e.target.id==='editor'){let data=Object.fromEntries(new FormData(e.target));data.ideas=data.ideas.split('\\n');data.published=data.published==='true';await api('admin',{...data,book:+$('#editBook').value});await sync();toast('Guide saved')}}catch(err){toast(err.message)}});\ndocument.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el)return;if(el.id==='close'||el.id==='adm')dialog.close();if(el.id==='account')account();const a=el.dataset.act,v=el.dataset.v;if(!a)return;try{if(a==='topic'){topic=v;for(const b of document.querySelectorAll('[data-act=topic]'))b.setAttribute('aria-pressed',String(b===el));results()}if(a==='minutes'){let p=state.progress;location.hash=href(by(p.book),p.idea,+v)}if(a==='mark'){const p=state.progress;let z=state.marks.find(x=>x.book===p.book&&x.idea===p.idea);if(!z){z={book:p.book,idea:p.idea,saved:0,tried:0};state.marks.push(z)}const on=!z[v];if(state.account)await persist('mark',{book:p.book,idea:p.idea,field:v,on});z[v]=+on;if(!state.account)saveLocal();reader(by(p.book),p.idea);document.querySelector('[data-v=\"'+v+'\"]').focus();toast(on?'Added to your notebook':'Notebook updated')}if(a==='create'){el.disabled=true;const r=await api('create',{});$('#modal').innerHTML=`<h2>Keep your reading key</h2><p>Use this key to sign in on another device. Anyone with it can access this reading account.</p><p class=\"key\">${esc(r.key)}</p><button data-act=\"copy\">Copy key</button>`;await enter(true);route()}if(a==='copy'){await navigator.clipboard.writeText($('.key').textContent);toast('Key copied')}if(a==='logout'){await seq.catch(()=>{});await api('logout',{});await sync();dialog.close();location.hash='#home';route()}}catch(err){el.disabled=false;toast(err.message)}});\nwindow.addEventListener('hashchange',()=>{route();window.scrollTo(0,0);main.focus({preventScroll:true})});document.addEventListener('keydown',e=>{if(e.key==='/'&&!dialog.open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();if(!$('#q'))location.hash='#library';setTimeout(()=>$('#q')?.focus(),25)}});sync().then(route).catch(e=>{main.textContent='Could not open the guide. Refresh to retry. '+e.message})\n})()","style.css":"*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f6f5ef;color:#20372e;font:16px/1.55 system-ui,sans-serif}a{color:inherit}button,input,select,textarea{font:inherit}button,.btn{cursor:pointer;border:1px solid #b6c3b8;color:#20372e;border-radius:7px;background:#fcfcf7;padding:.55rem .95rem;text-decoration:none;display:inline-block}button:hover,.btn:hover{background:#e1e9dc}.primary,.btn.primary{background:#214d3e;color:white;border-color:#214d3e}button:disabled{opacity:.5;cursor:default}:focus-visible{outline:3px solid #aa5b17;outline-offset:3px}.skip{position:absolute;top:-80px}.skip:focus{top:0;background:white;z-index:2}header{border-bottom:1px solid #cdd4ca;background:#fafbf5}.bar,main,footer{max-width:1290px;margin:auto;padding:0 clamp(18px,4vw,66px)}.bar{display:flex;align-items:center;gap:2.5rem;min-height:76px}.brand{font:700 1.7rem Georgia,serif;text-decoration:none;white-space:nowrap}.brand span{color:#547b50}nav{display:flex;gap:1.35rem;flex:1}nav a{font-size:.94rem;text-decoration:none;padding:.5rem 0}nav a[aria-current=page]{box-shadow:inset 0 -2px #3e6844}main{min-height:75vh;padding-top:2.4rem;padding-bottom:4rem}h1,h2,h3,p{margin:0 0 .8rem}h1,h2,h3{font-family:Georgia,serif;line-height:1.13;font-weight:500}h1{font-size:clamp(2.35rem,5vw,4.8rem);letter-spacing:-.045em}h2{font-size:clamp(1.65rem,3vw,2.5rem);letter-spacing:-.035em}h3{font-size:1.4rem}.hero{background:#213e32;color:#fbf7df;border-radius:14px;display:grid;grid-template-columns:1.5fr 1fr;align-items:center;overflow:hidden;padding:clamp(24px,4vw,55px);gap:1rem}.hero p{max-width:44ch;color:#e0ead9}.hero .btn{background:#e0ecab;border-color:#e0ecab;color:#20372e}.label{font-size:.8rem;letter-spacing:.095em;text-transform:uppercase;font-weight:650}.jacket{color:#fff5df;background:var(--cover,#80523e);overflow:hidden;position:relative;border-radius:2px 7px 7px 2px;box-shadow:inset 6px 0 0 #0002;display:flex;flex-direction:column;justify-content:space-between;padding:16px 15px;isolation:isolate}.jacket:after{content:\"\";position:absolute;right:-13%;bottom:-33%;width:90%;aspect-ratio:1;border:14px double #fff8;border-radius:50%;z-index:-1;transform:scaleY(1.55) rotate(25deg)}.jacket strong{font:500 clamp(1rem,2vw,1.5rem)/1.12 Georgia,serif;max-width:90%}.jacket small{font-size:.7rem;line-height:1.2}.art{display:flex;align-items:center;justify-content:center;height:210px}.art .jacket{width:138px;height:185px;transform:rotate(-8deg);box-shadow:6px 10px 16px #0004}.art .jacket+ .jacket{margin-left:-38px;transform:rotate(11deg) translateY(7px)}.section{margin-top:2rem}.heading,.row,.actions{display:flex;align-items:center;gap:.65rem;flex-wrap:wrap}.heading{justify-content:space-between;margin-bottom:1rem}.heading h2{margin:0}.query{width:100%;padding:.85rem 1rem;border-radius:8px;border:1px solid #95aa9d;background:#fff;font:inherit}.chips{display:flex;gap:.5rem;flex-wrap:wrap;margin:.85rem 0 1.6rem}.chips button[aria-pressed=true],button.active{background:#244738;color:white}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,225px),1fr));gap:1rem}.book,.panel,.item{border:1px solid #cbd4c8;border-radius:10px;background:#fcfcf8;padding:1.2rem}.book{display:flex;gap:1rem;align-items:center;color:inherit;text-decoration:none}.book:hover,.item:hover{border-color:#799575}.book .jacket{width:65px;height:90px;flex:none;padding:7px}.book .jacket strong{font-size:.8rem}.book .jacket small{display:none}.book h3{margin:.15rem 0 .3rem}.muted,small{color:#52685a}.jacket small{color:inherit}.shell{display:grid;grid-template-columns:240px minmax(0,720px);gap:clamp(24px,5vw,78px);align-items:start}.side{position:sticky;top:20px}.side details a{display:block;text-decoration:none;padding:.32rem 0;font-size:.92rem}.side details{max-height:65vh;overflow:auto}.reader{min-width:0}.reader h1{font-size:clamp(2.2rem,4vw,3.65rem)}.reader .panel{margin:1rem 0}.idea{border-left:4px solid #7e9958;background:#edf1df;padding:1.35rem;border-radius:5px}.idea h2{font-size:clamp(1.6rem,3vw,2.3rem)}.actions{margin:1rem 0}.stack{display:grid;gap:.65rem}.item{display:block;text-decoration:none}.dual{display:grid;grid-template-columns:1fr 1fr;gap:1rem}label{display:block;font-weight:600;margin:.65rem 0}label input,label select,textarea{display:block;width:100%;padding:.65rem;margin:.3rem 0;border:1px solid #95aa9d;border-radius:6px;background:white}summary{cursor:pointer;font-weight:600}.panel p:last-child{margin-bottom:0}footer{border-top:1px solid #cbd4c8;display:flex;gap:1rem;align-items:center;padding-top:1.2rem;padding-bottom:1.2rem;font-family:Georgia,serif}footer span,footer a{font: .88rem system-ui}footer a{margin-left:auto}dialog{width:min(92vw,540px);max-height:85vh;overflow:auto;color:#20372e;border:1px solid #90a48e;border-radius:14px;padding:1.5rem}dialog::backdrop{background:#162c25a8}#close{float:right}#modal{clear:both;padding-top:.7rem}#toast:not(:empty){position:fixed;bottom:1rem;left:50%;transform:translateX(-50%);background:#193d30;color:white;padding:.7rem 1rem;border-radius:8px;z-index:5}.key{overflow-wrap:anywhere;user-select:all;background:#edf1df;padding:.8rem}button,.btn,nav a{min-height:42px}@media(max-width:800px){.bar{flex-wrap:wrap;gap:0;justify-content:space-between;padding-top:.75rem}.bar nav{order:3;flex-basis:100%;justify-content:space-between;gap:.3rem}.bar nav a{font-size:.88rem}.shell{grid-template-columns:1fr;gap:1rem}.side{position:static}.side details{max-height:40vh}.hero{grid-template-columns:1.7fr 1fr}.art .jacket{width:92px;height:140px}.art .jacket:first-child{display:none}.art .jacket+.jacket{margin:0}.art{height:150px}.dual{grid-template-columns:1fr}}@media(max-width:480px){main{padding-top:1.15rem}.hero{grid-template-columns:1fr}.art{display:none}.grid{grid-template-columns:1fr}.bar .brand{font-size:1.45rem}.chips button{font-size:.9rem}footer{flex-wrap:wrap}footer span{display:none}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\nhtml[data-theme=dark]{color-scheme:dark}html[data-theme=dark] body{background:#111915;color:#e1eade}html[data-theme=dark] :is(header,.book,.panel,.item,dialog){background:#1b2821;color:#e1eade;border-color:#536959}html[data-theme=dark] :is(button,.btn,input,textarea,select){background:#273b30;color:#edf1e9;border-color:#677c69}html[data-theme=dark] :is(.idea,.key){background:#293d30;color:#edf3e7}html[data-theme=dark] :is(small,.muted){color:#bdccbe}html[data-theme=dark] .chips button[aria-pressed=true]{background:#b7d19e;color:#132319}html[data-theme=dark] .hero .btn{background:#cce0a6;color:#24351f}@media(max-width:800px){.bar #theme{margin-left:auto;margin-right:.4rem}.bar nav{order:4}}@media(max-width:410px){.bar #theme,.bar #account{font-size:.83rem;padding:.4rem}.bar .brand{font-size:1.28rem}}\n","books.json":"[\n  {\n    \"id\": 0,\n    \"title\": \"The Inner Game of Tennis\",\n    \"author\": \"W. Timothy Gallwey\",\n    \"topic\": \"Practice\",\n    \"overview\": \"Under pressure, the voice reviewing your performance can interrupt the skill you have already learned. Gallwey uses tennis to explore how curiosity, sensory attention and trust change practice.\",\n    \"example\": \"Overthinking a contest? After a failed test, record the smallest input that failed and what it returned. That observation gives your next attempt a direction.\",\n    \"limit\": \"A technique for directing attention cannot replace learning the underlying skill.\",\n    \"ideas\": [\n      \"Describe the landing spot before rating the shot\",\n      \"Choose one observable cue for the next attempt\",\n      \"Separate feedback time from performance time\",\n      \"Notice the exact moment your attention drifts\",\n      \"Let a familiar movement run once without verbal coaching\",\n      \"Use a mental image of the desired result\",\n      \"Treat an opponent as someone who reveals a weakness\",\n      \"Measure concentration by how gently you return to the task\",\n      \"Experiment with grip or timing one variable at a time\",\n      \"After a match, record one discovery you can test tomorrow\",\n      \"Divide a performance into preparation, execution and review\",\n      \"Use the sound of contact as a single attention cue\",\n      \"Observe a skilled demonstration before requesting instructions\",\n      \"Practice recovering after an error as its own skill\",\n      \"Choose one aim you control before competitive play\",\n      \"Repeat a successful movement while attending to its feel\",\n      \"Leave room for surprise when predicting your own result\",\n      \"Treat boredom as a signal to change what you observe\",\n      \"Watch how self-talk shifts after success as well as failure\",\n      \"Compare two sessions using the same process measure\",\n      \"Ask a coach for descriptive feedback\",\n      \"Use a brief reset between attempts\",\n      \"Distinguish a scoreboard target from a learning target\",\n      \"Try a lower-stakes rehearsal of a pressure situation\",\n      \"End practice by recalling one movement you want to repeat\"\n    ],\n    \"source\": \"https://theinnergame.com/the-inner-game-of-tennis/\",\n    \"cases\": [\n      \"Two hidden tests failed. Write down the input, expected output and actual output. The description gives you three facts to inspect when the sentence ‘I am bad at contests’ gives you none.\",\n      \"During a timed proof, hold one question in mind: what exactly must this line establish? Return to that question whenever you start estimating your rank.\",\n      \"Rehearse a two-minute project introduction straight through. Only after it ends, listen to the recording and choose one sentence to revise. Notice what happens to your delivery when you stop editing mid-sentence.\",\n      \"While reading a proof, put a pencil mark beside the first line you cannot explain. Rereading from that line gives you a precise place to work.\",\n      \"Type a familiar function once without mentally narrating each keystroke. Then review it deliberately. Which mistakes did the slower review catch?\",\n      \"Before changing a dashboard, sketch how the finished screen should answer a visitor’s question. Keep that concrete picture visible through the first revision.\",\n      \"A stronger chess opponent keeps reaching your back rank. Save one position and work out which earlier choice allowed it. The result of the game becomes a training example.\",\n      \"During a mock interview you notice yourself planning what the interviewer will think. Bring your attention back to the input constraints and say one of them aloud.\",\n      \"If a classifier improves after changing both the data split and the feature set, rerun with one change at a time. Record which change moved the metric.\",\n      \"After a contest, finish the sentence ‘I wonder whether…’ with a question that a tiny test case can answer. Run it once before your next contest.\"\n    ],\n    \"lessons\": [\n      [\n        \"A description preserves details you can test.\",\n        \"Rewrite a mistake using only facts a camera or log could record.\"\n      ],\n      [\n        \"One cue gives attention somewhere to return during pressure.\",\n        \"Pick a cue for your next attempt and record when you used it.\"\n      ],\n      [\n        \"Reviewing during execution divides attention.\",\n        \"Record an uninterrupted explanation and review it afterward.\"\n      ],\n      [\n        \"The first moment of confusion makes a precise starting point.\",\n        \"Mark the first proof step you cannot explain.\"\n      ],\n      [\n        \"A familiar sequence can run with less conscious direction.\",\n        \"Perform it once smoothly, then review its result.\"\n      ],\n      [\n        \"Imagining an outcome helps you recognize it.\",\n        \"Sketch the desired output before your next revision.\"\n      ],\n      [\n        \"A difficult opponent reveals repeatable weaknesses.\",\n        \"Turn one recurring loss into a drill.\"\n      ],\n      [\n        \"Returning attention is itself a practice opportunity.\",\n        \"Choose a reset cue for your next three distractions.\"\n      ],\n      [\n        \"Changing two variables obscures the cause of improvement.\",\n        \"Repeat one test with only one condition changed.\"\n      ],\n      [\n        \"A testable question carries learning into the next session.\",\n        \"Turn one surprise into a prediction.\"\n      ]\n    ]\n  },\n  {\n    \"id\": 1,\n    \"title\": \"Mastery\",\n    \"author\": \"Robert Greene\",\n    \"topic\": \"Practice\",\n    \"overview\": \"Greene describes long apprenticeships in which close observation, repetition, mentorship and independent experiments develop judgment. His historical portraits invite you to look for the less visible work behind expertise.\",\n    \"example\": \"To learn debugging, read a maintainer’s diagnosis, predict the next test, then compare. Keep the prediction you got wrong.\",\n    \"limit\": \"Success stories select for survivors. Access to time, opportunity and instruction affects the path.\",\n    \"ideas\": [\n      \"List problems you keep returning to voluntarily\",\n      \"Map the basic skills your field rewards\",\n      \"Study how experienced people spend an ordinary day\",\n      \"Practice one weak subskill with immediate feedback\",\n      \"Ask a mentor to critique a specific decision\",\n      \"Copy a technique in private practice to understand its mechanics\",\n      \"Work with people whose strengths expose your blind spots\",\n      \"Combine two fields in a small experiment\",\n      \"Compare your instincts with measured results\",\n      \"Create a project that forces independent judgment\",\n      \"Keep a log of mistakes that recur across projects\",\n      \"Read an expert’s early work to notice development\",\n      \"Find out which constraints shaped an admired solution\",\n      \"Practice giving feedback as well as receiving it\",\n      \"Seek a second mentor for a different weakness\",\n      \"Use an unfamiliar tool to expose an assumption\",\n      \"Study the history of a technique before changing it\",\n      \"Work on a question that survives initial frustration\",\n      \"Invite a critic to test your favorite explanation\",\n      \"Set aside an attractive feature to finish a working whole\",\n      \"Explain an intuition as a prediction you can check\",\n      \"Use a small prototype to investigate a large concept\",\n      \"Study a neighboring discipline for a transferable method\",\n      \"Rebuild a past project under a new constraint\",\n      \"Review your work over months to spot emerging strengths\"\n    ],\n    \"source\": \"https://www.penguinrandomhouse.com/authors/243460/robert-greene/\",\n    \"cases\": [\n      \"Review the last five projects you built without being assigned them. Circle the part of each project you kept refining after the minimum requirement worked. Look for a recurring question.\",\n      \"Pick a repository you admire. Draw the path from input to storage to output. Mark one part you can already rebuild and one part that would force you to learn a new skill.\",\n      \"Read one completed pull request from a maintainer. How much of their effort went into understanding the bug, writing the change, testing it, and explaining it to others?\",\n      \"Choose one weakness such as proving a loop invariant. Practice on three short loops and check the invariant after every iteration with a hand-written trace.\",\n      \"Send a mentor one design choice, the alternatives you considered, and the constraint that decided it. Ask which assumption they would test first.\",\n      \"Rebuild a small search interface from memory. Then examine the original interaction and identify the first decision your reconstruction missed.\",\n      \"Pair with someone who approaches a problem through examples while you prefer abstractions. Predict where your solution might fail, then compare the two lists.\",\n      \"Use graph traversal to explore links between the books in your reading list. Which questions become easier once the material is represented as a network?\",\n      \"Before benchmarking a change, record your expected winner and why. The cases that surprise you tell you where intuition needs calibration.\",\n      \"Build a small tool for someone who can actually reject it. Ask them to try the first version while you watch silently. Their choices will test your independent judgment.\"\n    ],\n    \"lessons\": [\n      [\n        \"Voluntary effort reveals interests worth cultivating.\",\n        \"Circle the part of three projects you kept doing willingly.\"\n      ],\n      [\n        \"A map of component skills makes an ambition trainable.\",\n        \"Break one feature into three skills and choose the weakest.\"\n      ],\n      [\n        \"Routine decisions reveal work hidden by polished results.\",\n        \"Trace a merged change from report to verification.\"\n      ],\n      [\n        \"Immediate feedback connects correction with a specific attempt.\",\n        \"Run three small drills and review each result.\"\n      ],\n      [\n        \"A precise question helps a mentor examine your reasoning.\",\n        \"Ask which assumption behind one decision deserves testing.\"\n      ],\n      [\n        \"Reconstruction exposes choices an observer misses.\",\n        \"Rebuild a small interaction from memory and compare.\"\n      ],\n      [\n        \"Different strengths expose different errors.\",\n        \"Ask a peer to test your most confident assumption.\"\n      ],\n      [\n        \"Transferring a method tests understanding.\",\n        \"Use a diagramming technique outside its usual subject.\"\n      ],\n      [\n        \"Written predictions make intuition easier to calibrate.\",\n        \"Predict one benchmark result before measuring.\"\n      ],\n      [\n        \"Real users give independent judgment a meaningful test.\",\n        \"Watch someone use your feature without instructions.\"\n      ]\n    ]\n  },\n  {\n    \"id\": 2,\n    \"title\": \"Grit\",\n    \"author\": \"Angela Duckworth\",\n    \"topic\": \"Practice\",\n    \"overview\": \"Duckworth connects sustained interest and effort with long-term achievement. The book explores how interests develop, why purposeful practice matters and how groups reinforce persistence.\",\n    \"example\": \"If an open-source issue stalls, separate your long-term aim of contributing from your current tactic. A smaller reproducible case may serve that aim better.\",\n    \"limit\": \"Persistence has opportunity costs. Reassess a goal when the costs, evidence or your circumstances change.\",\n    \"ideas\": [\n      \"Name the long-term aim behind a short-term task\",\n      \"Separate the goal from the tactic\",\n      \"Give an emerging interest a second encounter\",\n      \"Choose a weakness you can practice deliberately\",\n      \"Specify what useful feedback would look like\",\n      \"Connect a dull repetition to someone it helps\",\n      \"Record an improvement that came after a setback\",\n      \"Find peers who practice the same craft\",\n      \"Break a distant ambition into intermediate goals\",\n      \"Review the cost of continuing at a fixed decision point\",\n      \"Try several activities before specializing\",\n      \"Notice which questions become more interesting with familiarity\",\n      \"Ask a practitioner what the unglamorous work looks like\",\n      \"Use a short drill with a clear finish\",\n      \"Repeat a drill after receiving corrective feedback\",\n      \"Look for the part of routine practice you avoid\",\n      \"Identify a person who benefits when your work improves\",\n      \"Try a new approach to a blocked intermediate goal\",\n      \"Keep a record of the strategies you have already tested\",\n      \"Make practice materials easy to reach\",\n      \"Offer a teammate encouragement tied to a specific effort\",\n      \"Treat a temporary slump as a question to investigate\",\n      \"Notice when belonging to a group changes your persistence\",\n      \"Choose a realistic horizon for judging improvement\",\n      \"Retire a low-level goal when a better route serves the same purpose\"\n    ],\n    \"source\": \"https://www.angeladuckworth.com/grit\",\n    \"cases\": [\n      \"If an issue you proposed is declined, write out the reason you wanted to solve it. A different issue might serve the same long-term aim.\",\n      \"Learning algorithms is a goal. Solving one particular puzzle tonight is a tactic. Try a simpler related puzzle if it exposes the concept that blocked you.\",\n      \"Revisit a subject you dismissed after one lecture. Try a practical example and note whether curiosity grows when the format changes.\",\n      \"Skip the full mock contest once and drill the specific transition that cost you time, such as turning an invariant into a boundary check.\",\n      \"Before practicing a presentation, ask a friend to identify the first term they cannot explain. That gives a precise signal for the next revision.\",\n      \"Connect a repetitive test-writing task to the user who would otherwise lose saved work. It becomes easier to tell which tests actually matter.\",\n      \"After a failed attempt, record what changed on the next run. A narrower bug report counts as progress even when the fix is still unfinished.\",\n      \"Compare study notes with someone who has kept practicing the same skill for a semester. Ask what their ordinary week looks like.\",\n      \"Break ‘contribute to a library’ into reproducing an issue, tracing the call path, proposing a failing test, and explaining the fix.\",\n      \"Before a difficult project week, decide what new evidence would justify another week. At the checkpoint, compare the evidence with the cost of postponing your other work.\"\n    ],\n    \"lessons\": [\n      [\n        \"A lasting aim can survive losing one opportunity.\",\n        \"Write another route to your original goal.\"\n      ],\n      [\n        \"Several tactics can serve the same commitment.\",\n        \"Choose a simpler problem that exercises the same skill.\"\n      ],\n      [\n        \"Interest sometimes grows during a second encounter.\",\n        \"Retry a subject through one practical example.\"\n      ],\n      [\n        \"An isolated weakness is easier to measure.\",\n        \"Repeat one difficult transition three times.\"\n      ],\n      [\n        \"Precise feedback identifies a next adjustment.\",\n        \"Ask a listener to identify the first confusing sentence.\"\n      ],\n      [\n        \"A beneficiary gives repetition a purpose.\",\n        \"Name one person who benefits from today's practice.\"\n      ],\n      [\n        \"A setback can narrow the search for a better approach.\",\n        \"Record one possibility your last attempt ruled out.\"\n      ],\n      [\n        \"Peers make the ordinary routines behind achievement visible.\",\n        \"Ask someone what a typical practice session looks like.\"\n      ],\n      [\n        \"Intermediate goals turn ambition into observable progress.\",\n        \"Choose one milestone someone else could verify.\"\n      ],\n      [\n        \"Persistence has an opportunity cost.\",\n        \"Set a checkpoint and name the evidence that would justify continuing.\"\n      ]\n    ]\n  },\n  {\n    \"id\": 3,\n    \"title\": \"Factfulness\",\n    \"author\": \"Hans Rosling, Ola Rosling & Anna Rosling Rönnlund\",\n    \"topic\": \"Judgment\",\n    \"overview\": \"The authors examine recurring errors in how people picture the world. Their examples invite readers to check distributions, rates and historical trends before accepting a dramatic explanation.\",\n    \"example\": \"A dashboard shows twice as many errors this week. Compare errors per thousand requests before concluding that reliability fell.\",\n    \"limit\": \"A global improvement can coexist with a serious local problem. Choose the scale relevant to your decision.\",\n    \"ideas\": [\n      \"Look for the middle hidden by two labels\",\n      \"Compare the present with a dated baseline\",\n      \"Sketch several possible shapes for a trend\",\n      \"Check frequency alongside the frightening example\",\n      \"Divide a count by the population exposed\",\n      \"Inspect variation inside a category\",\n      \"Update a belief that depends on old data\",\n      \"Ask a specialist from a second discipline\",\n      \"Trace the system behind a convenient culprit\",\n      \"When urgency rises, identify one fact worth checking\"\n    ],\n    \"source\": \"https://www.gapminder.org/factfulness/instincts/\"\n  },\n  {\n    \"id\": 4,\n    \"title\": \"The Almanack of Naval Ravikant\",\n    \"author\": \"Eric Jorgenson, compiling Naval Ravikant\",\n    \"topic\": \"Judgment\",\n    \"overview\": \"This collection presents Naval’s views on building wealth, judgment and a satisfying life. Read the aphorisms as propositions to test against your own goals and constraints.\",\n    \"example\": \"A reusable extension helps new users after you finish coding. Ask how much maintenance each additional user creates before calling it leverage.\",\n    \"limit\": \"Personal philosophy and entrepreneurial anecdotes do not establish predictable financial outcomes.\",\n    \"ideas\": [\n      \"Identify a skill you learn unusually willingly\",\n      \"Make a reusable output from a recurring task\",\n      \"Track the maintenance cost of leverage\",\n      \"Choose collaborators you can imagine trusting for years\",\n      \"Write down a decision before seeing its outcome\",\n      \"Separate wanting an outcome from wanting status\",\n      \"Protect time for reading outside your immediate field\",\n      \"Notice which desires make an ordinary day feel insufficient\",\n      \"Calculate what an obligation costs in attention\",\n      \"Define what enough would look like for one goal\"\n    ],\n    \"source\": \"https://www.navalmanack.com/\"\n  },\n  {\n    \"id\": 5,\n    \"title\": \"The Back of the Napkin\",\n    \"author\": \"Dan Roam\",\n    \"topic\": \"Judgment\",\n    \"overview\": \"Roam treats simple drawings as tools for understanding a problem and explaining it to someone else. The useful drawing changes with the question you are asking.\",\n    \"example\": \"For a slow checkout flow, draw the steps in order, then plot time spent at each step. The two drawings answer different questions.\",\n    \"limit\": \"A clean sketch can hide missing evidence. Mark uncertain links before treating the drawing as an explanation.\",\n    \"ideas\": [\n      \"Draw the people and objects involved\",\n      \"Use bars to compare quantities\",\n      \"Map where components sit in relation to one another\",\n      \"Use a timeline when order matters\",\n      \"Draw arrows to show how inputs change\",\n      \"Put competing explanations side by side\",\n      \"Look at the raw material before choosing a template\",\n      \"Remove detail that obscures the decision\",\n      \"Ask another person to redraw your explanation\",\n      \"Circle the missing fact the sketch reveals\"\n    ],\n    \"source\": \"https://www.penguinrandomhouse.com/books/300247/the-back-of-the-napkin-expanded-edition-by-dan-roam/9781591842699/\"\n  },\n  {\n    \"id\": 6,\n    \"title\": \"Evolutionary Psychology\",\n    \"author\": \"Topic guide · edition unconfirmed\",\n    \"topic\": \"Mind\",\n    \"overview\": \"This editorial guide explores how researchers ask whether evolutionary history helps explain behavior. Each explanation needs predictions that distinguish it from alternatives.\",\n    \"example\": \"If people defer to a confident speaker, compare cases where confidence, expertise and social rank point in different directions.\",\n    \"limit\": \"An appealing origin story is a hypothesis. Culture, learning and individual variation also deserve tests.\",\n    \"ideas\": [\n      \"Separate an immediate trigger from a historical explanation\",\n      \"Write a prediction before looking at outcomes\",\n      \"List a competing learning-based explanation\",\n      \"Ask what observation would weaken each account\",\n      \"Check which populations a study sampled\",\n      \"Look for variation within each group\",\n      \"Distinguish an adaptation claim from a by-product claim\",\n      \"Consider how environments change the payoff of behavior\",\n      \"Keep descriptive explanations separate from ethical judgments\",\n      \"Revise the hypothesis when predictions repeatedly fail\"\n    ],\n    \"source\": \"https://openlibrary.org/search?q=Evolutionary%20Psychology%20\"\n  },\n  {\n    \"id\": 7,\n    \"title\": \"Slow Sex\",\n    \"author\": \"Topic guide · edition unconfirmed\",\n    \"topic\": \"Relationships\",\n    \"overview\": \"This editorial guide explores unhurried intimacy between consenting adults. Its questions center on mutual attention, comfort and communication.\",\n    \"example\": \"Before a date, talk about what makes each person feel relaxed and what either person would like to leave open.\",\n    \"limit\": \"Comfort and desire are individual. Consent is ongoing and either person can stop at any time.\",\n    \"ideas\": [\n      \"Ask what closeness means to each person\",\n      \"Choose a moment when both people have time\",\n      \"Talk about boundaries in ordinary language\",\n      \"Leave room for a genuine change of mind\",\n      \"Notice distractions and agree which to remove\",\n      \"Ask before interpreting silence\",\n      \"Use a short check-in about comfort\",\n      \"Make affection possible without an expected outcome\",\n      \"Discuss different preferences without assigning blame\",\n      \"Afterward ask what felt comfortable to repeat\"\n    ],\n    \"source\": \"https://openlibrary.org/search?q=Slow%20Sex%20\"\n  },\n  {\n    \"id\": 8,\n    \"title\": \"How to Do the Work\",\n    \"author\": \"Nicole LePera\",\n    \"topic\": \"Mind\",\n    \"overview\": \"LePera writes about noticing habitual responses, examining learned patterns and practicing different choices. Use the book’s prompts as a way to observe everyday behavior.\",\n    \"example\": \"When a code review feels personal, write down the comment, your interpretation and the response you want to send.\",\n    \"limit\": \"The exercises are self-reflection tools. The author’s broader health explanations require independent evidence.\",\n    \"ideas\": [\n      \"Identify a recurring situation in concrete terms\",\n      \"Write the first interpretation you made\",\n      \"Notice the feeling before choosing a response\",\n      \"Trace a familiar rule you absorbed growing up\",\n      \"Check whether that rule still serves you\",\n      \"Choose one small promise you can keep\",\n      \"State a boundary in terms of your own actions\",\n      \"Notice what makes a new habit easier\",\n      \"Repair a misstep with one specific action\",\n      \"Review a week of observations for patterns\"\n    ],\n    \"source\": \"https://www.hachetteindia.com/Home/bookdetails/Info/9781409197744/how-to-do-the-work\"\n  },\n  {\n    \"id\": 9,\n    \"title\": \"The Myth of Normal\",\n    \"author\": \"Gabor Maté with Daniel Maté\",\n    \"topic\": \"Mind\",\n    \"overview\": \"The authors ask readers to look at health in the context of relationships, workplaces and culture. They invite inquiry into pressures that a community has come to accept.\",\n    \"example\": \"If everyone on a team routinely skips breaks, examine deadlines and incentives before attributing the pattern to individual choices.\",\n    \"limit\": \"Social context matters, but an individual illness has no single cause established by these reflections.\",\n    \"ideas\": [\n      \"Question which pressures a group has normalized\",\n      \"Describe the cost of always being available\",\n      \"Notice when belonging requires hiding a preference\",\n      \"Ask what a coping habit is doing for someone\",\n      \"Look for pressures shared across a group\",\n      \"Explore a recurring reaction with curiosity\",\n      \"Practice expressing a small need\",\n      \"Identify one supportive relationship\",\n      \"Distinguish a personal account from causal evidence\",\n      \"Name one structural change that could ease the load\"\n    ],\n    \"source\": \"https://drgabormate.com/book/the-myth-of-normal/\"\n  },\n  {\n    \"id\": 10,\n    \"title\": \"Scattered Minds\",\n    \"author\": \"Gabor Maté\",\n    \"topic\": \"Mind\",\n    \"overview\": \"Maté explores attention difficulties through personal stories and a developmental lens. The reading questions emphasize compassion, environmental supports and careful interpretation of causal claims.\",\n    \"example\": \"If you keep losing an assignment between apps, put the single next action in one visible place and see whether follow-through changes.\",\n    \"limit\": \"The book’s developmental explanation is the author’s view. ADHD has multiple contributing factors and diagnosis requires clinical assessment.\",\n    \"ideas\": [\n      \"Describe the difficulty without attaching a character judgment\",\n      \"Track the circumstances around a lapse\",\n      \"Separate remembering a task from starting it\",\n      \"Move a reminder to the point of action\",\n      \"Make the first step visible and small\",\n      \"Find out which distractions are controllable\",\n      \"Ask what kind of support the person wants\",\n      \"Notice strengths alongside difficulties\",\n      \"Distinguish family stories from proof of cause\",\n      \"Bring recurring impairments and concrete examples to a qualified clinician\"\n    ],\n    \"source\": \"https://www.nimh.nih.gov/health/topics/attention-deficit-hyperactivity-disorder-adhd\"\n  },\n  {\n    \"id\": 11,\n    \"title\": \"The Body Keeps the Score\",\n    \"author\": \"Bessel van der Kolk\",\n    \"topic\": \"Mind\",\n    \"overview\": \"Van der Kolk draws on clinical experiences to discuss how traumatic experiences can affect attention, bodily sensations and relationships. The book also surveys different approaches to recovery.\",\n    \"example\": \"When a friend describes distress, ask whether they want company, practical help or space before offering interpretations.\",\n    \"limit\": \"Anecdotes cannot establish a treatment’s effectiveness. For care decisions, use current clinical guidance and qualified support.\",\n    \"ideas\": [\n      \"Let a person decide what they wish to disclose\",\n      \"Ask what would make the current setting feel safer\",\n      \"Respect differences between people with similar histories\",\n      \"Distinguish a present observation from an inferred cause\",\n      \"Notice how predictable routines can support choice\",\n      \"Ask permission before physical contact\",\n      \"Use ordinary language to describe distress\",\n      \"Recognize the limits of a case history\",\n      \"Check independent evidence for a proposed treatment\",\n      \"Let the person set the pace of a support conversation\"\n    ],\n    \"source\": \"https://www.nimh.nih.gov/health/topics/post-traumatic-stress-disorder-ptsd\"\n  },\n  {\n    \"id\": 12,\n    \"title\": \"The Cost of Being a Man\",\n    \"author\": \"Topic guide · title unconfirmed\",\n    \"topic\": \"Relationships\",\n    \"overview\": \"These editorial prompts examine expectations associated with masculinity, including self-reliance, risk, work and emotional expression. They do not assume that everyone experiences those pressures alike.\",\n    \"example\": \"A friend says he is fine after a setback. Offer a concrete invitation for a walk and let him choose whether to talk.\",\n    \"limit\": \"A cultural expectation can shape choices without describing every individual in a group.\",\n    \"ideas\": [\n      \"Name one unwritten expectation in your peer group\",\n      \"Ask who benefits when that expectation is followed\",\n      \"Notice when a joke discourages honesty\",\n      \"Practice asking for a specific kind of help\",\n      \"Separate reliability from constant availability\",\n      \"Make space for a quieter member of a group\",\n      \"Identify a friendship built on mutual disclosure\",\n      \"Question a risk taken chiefly for approval\",\n      \"Discuss how expectations vary between generations\",\n      \"Choose one expectation to keep or revise\"\n    ],\n    \"source\": \"https://openlibrary.org/search?q=The%20Cost%20of%20Being%20a%20Man%20\"\n  },\n  {\n    \"id\": 13,\n    \"title\": \"The Book of Man\",\n    \"author\": \"Osho\",\n    \"topic\": \"Relationships\",\n    \"overview\": \"Read these talks as philosophical provocations about identity, roles and awareness. Their value lies in questions you can examine in your life.\",\n    \"example\": \"Ask which parts of your career ambition you would still pursue if nobody could see the title.\",\n    \"limit\": \"Spiritual commentary is interpretive. Broad descriptions of men and women deserve scrutiny.\",\n    \"ideas\": [\n      \"Describe yourself without job or status labels\",\n      \"Examine an ambition inherited from others\",\n      \"Notice a role you perform for approval\",\n      \"Ask what independence means within a relationship\",\n      \"Observe a reaction before explaining it\",\n      \"Reflect on a time vulnerability strengthened trust\",\n      \"Identify a belief that experience has changed\",\n      \"Question a generalization about gender\",\n      \"Try a quiet period without an audience\",\n      \"Translate one abstract value into a daily choice\"\n    ],\n    \"source\": \"https://openlibrary.org/search?q=The%20Book%20of%20Man%20Osho\"\n  },\n  {\n    \"id\": 14,\n    \"title\": \"Men Are from Mars, Women Are from Venus\",\n    \"author\": \"John Gray\",\n    \"topic\": \"Relationships\",\n    \"overview\": \"Gray uses a gender-based metaphor to discuss misunderstandings around support, stress and communication. Treat the scenarios as prompts for asking a particular person what works for them.\",\n    \"example\": \"A teammate describes a difficult day. Ask whether they want to vent or brainstorm before offering a fix.\",\n    \"limit\": \"The book’s binary generalizations are an unreliable guide to an individual person’s preferences.\",\n    \"ideas\": [\n      \"Ask whether listening or advice would help\",\n      \"Reflect the concern in your own words\",\n      \"Clarify an ambiguous request for space\",\n      \"Agree when to return to a paused conversation\",\n      \"Describe one need without assigning motive\",\n      \"Ask how the other person recognizes appreciation\",\n      \"Offer a specific example of support you value\",\n      \"Check whether an assumption fits this person\",\n      \"Repair a misunderstanding by naming your part\",\n      \"Revisit a communication agreement as needs change\"\n    ],\n    \"source\": \"https://openlibrary.org/search?q=Men%20Are%20from%20Mars%2C%20Women%20Are%20from%20Venus%20John%20Gray\"\n  },\n  {\n    \"id\": 15,\n    \"title\": \"The Art of War\",\n    \"author\": \"Sun Tzu\",\n    \"topic\": \"Judgment\",\n    \"overview\": \"Read here as a historical text on planning and judgment. The practical exercises apply its themes to choosing projects, managing resources and reducing needless competition.\",\n    \"example\": \"Before a hackathon, find the smallest end-to-end demo the judges can actually evaluate. Compare its time cost with adding another feature.\",\n    \"limit\": \"Historical strategy is an analogy for project work. Classmates and collaborators have interests worth understanding on their own terms.\",\n    \"ideas\": [\n      \"Define what success would accomplish\",\n      \"Inventory the resources you actually control\",\n      \"Learn the constraints of the setting\",\n      \"Estimate the cost of a prolonged project\",\n      \"Choose a problem where your skills are relevant\",\n      \"Understand incentives before making commitments\",\n      \"Keep options open while information is changing\",\n      \"Avoid a contest whose reward is mostly symbolic\",\n      \"Adjust a plan when assumptions fail\",\n      \"Review which outcome was achieved with the least waste\"\n    ],\n    \"source\": \"https://openlibrary.org/search?q=The%20Art%20of%20War%20Sun%20Tzu\"\n  },\n  {\n    \"id\": 16,\n    \"title\": \"Sisu\",\n    \"author\": \"Topic guide · edition unconfirmed\",\n    \"topic\": \"Practice\",\n    \"overview\": \"This editorial guide examines the Finnish concept of resolve under adversity. Its practical questions ask where a final effort helps and where recovery or help is the wiser choice.\",\n    \"example\": \"A stubborn test failure may reward another focused attempt if you have a new hypothesis. Repeating the same guess provides little information.\",\n    \"limit\": \"Endurance has costs. Pain, danger and exhaustion deserve attention.\",\n    \"ideas\": [\n      \"Define the obstacle in one sentence\",\n      \"Name a reason the effort matters to you\",\n      \"Choose the smallest meaningful next step\",\n      \"Distinguish discomfort from a signal to stop\",\n      \"Ask for help before exhausting your options\",\n      \"Prepare a fallback for a difficult day\",\n      \"Use previous setbacks to identify available resources\",\n      \"Schedule recovery after a demanding effort\",\n      \"Set a stopping condition before fatigue peaks\",\n      \"Record what helped you act despite uncertainty\"\n    ],\n    \"source\": \"https://openlibrary.org/search?q=Sisu%20\"\n  },\n  {\n    \"id\": 17,\n    \"title\": \"The 48 Laws of Power\",\n    \"author\": \"Robert Greene\",\n    \"topic\": \"Influence\",\n    \"overview\": \"Greene offers historical stories about power, status and incentives. This guide uses them to recognize social dynamics and choose transparent, ethical responses.\",\n    \"example\": \"In a project meeting, list who decides, who supplies evidence and whose workload changes. Invite the missing perspective before the decision.\",\n    \"limit\": \"Historical anecdotes can illustrate a pattern while leaving its frequency and alternatives unknown.\",\n    \"ideas\": [\n      \"Identify who controls a decision\",\n      \"Watch how credit is distributed\",\n      \"Notice when a public disagreement threatens status\",\n      \"Keep records of commitments that affect your work\",\n      \"Distinguish a polished reputation from actual reliability\",\n      \"Ask what an apparent favor obliges you to do\",\n      \"Recognize attempts to manufacture scarcity\",\n      \"Look for people excluded from informal conversations\",\n      \"Choose when a public response is necessary\",\n      \"Weigh the long-term trust cost of a short-term advantage\"\n    ],\n    \"source\": \"https://www.penguinrandomhouse.com/authors/243460/robert-greene/\"\n  },\n  {\n    \"id\": 18,\n    \"title\": \"The Art of Seduction\",\n    \"author\": \"Robert Greene\",\n    \"topic\": \"Influence\",\n    \"overview\": \"Greene studies historical portrayals of charisma, attention and persuasion. The editorial exercises examine how to recognize influence and preserve genuine choice.\",\n    \"example\": \"An invitation feels irresistible because it expires in ten minutes. Ask what makes it valuable when the countdown disappears.\",\n    \"limit\": \"Historical narratives are selective. In relationships respect consent, clarity and the other person’s ability to decline.\",\n    \"ideas\": [\n      \"Notice which details first captured your attention\",\n      \"Separate curiosity from confidence in a promise\",\n      \"Ask what information is being withheld\",\n      \"Watch for praise tailored to an insecurity\",\n      \"Notice a story that invites you to fill in the gaps\",\n      \"Check whether urgency leaves room to think\",\n      \"Recognize inconsistent attention that keeps you guessing\",\n      \"Compare someone's stated intentions with their behavior\",\n      \"Keep independent friendships and sources of perspective\",\n      \"Practice making an invitation easy to decline\"\n    ],\n    \"source\": \"https://www.penguinrandomhouse.com/authors/243460/robert-greene/\"\n  },\n  {\n    \"id\": 19,\n    \"title\": \"The Laws of Human Nature\",\n    \"author\": \"Robert Greene\",\n    \"topic\": \"Influence\",\n    \"overview\": \"Greene draws on biographies to discuss emotion, self-image, conformity and character. Read the patterns as hypotheses to check against repeated behavior.\",\n    \"example\": \"A terse review seems hostile. List two explanations and look for evidence across several interactions before deciding what it means.\",\n    \"limit\": \"Confidence in reading motives can outpace accuracy. Ask and observe before assigning a trait.\",\n    \"ideas\": [\n      \"Name your emotional state before a consequential decision\",\n      \"Look for patterns across repeated choices\",\n      \"Consider how incentives change someone’s presentation\",\n      \"Ask what would challenge your first impression\",\n      \"Notice when comparison turns into resentment\",\n      \"Identify the pressure to agree with a group\",\n      \"Examine the belief you most want to be true\",\n      \"Seek a perspective outside your usual circle\",\n      \"Use curiosity to interrupt a defensive reaction\",\n      \"Distinguish empathy from certainty about another mind\"\n    ],\n    \"source\": \"https://www.penguinrandomhouse.com/authors/243460/robert-greene/\"\n  },\n  {\n    \"id\": 20,\n    \"title\": \"The Greatest Lessons of History\",\n    \"author\": \"Topic guide · title unconfirmed\",\n    \"topic\": \"Judgment\",\n    \"overview\": \"These editorial prompts explore how to reason from history when the exact title on the reading list is uncertain. Compare contexts, sources and incentives before transferring a lesson.\",\n    \"example\": \"Two startups grew during recessions. Check industry, funding and timing before attributing both successes to the same cause.\",\n    \"limit\": \"Historical parallels can suggest a question. Their differences determine whether the answer travels.\",\n    \"ideas\": [\n      \"Date the original account and identify its audience\",\n      \"Separate contemporary testimony from later interpretation\",\n      \"Ask whose experiences the archive leaves out\",\n      \"Build a timeline before proposing a cause\",\n      \"Compare a similar case with a different outcome\",\n      \"Separate a trigger from a long-running condition\",\n      \"Identify which institutions shaped the options\",\n      \"Look for a base rate behind a memorable event\",\n      \"Name the differences that weaken an analogy\",\n      \"State the lesson with explicit conditions\"\n    ],\n    \"source\": \"https://openlibrary.org/search?q=The%20Greatest%20Lessons%20of%20History%20\"\n  }\n]","app.py":"import hashlib\nimport json\nimport os\nimport secrets\nimport sqlite3\nimport time\nfrom pathlib import Path\n\nfrom flask import Flask, abort, g, jsonify, request, send_from_directory\n\nROOT = Path(__file__).resolve().parent\napp = Flask(__name__, static_folder=None)\napp.config['MAX_CONTENT_LENGTH'] = 256_000\nBOOKS = json.loads((ROOT / 'books.json').read_text())\nSCHEMA = (ROOT / 'schema.sql').read_text()\n\ndef db():\n    if 'db' not in g:\n        g.db = sqlite3.connect(os.environ.get('MARGINALIA_DB', ROOT / 'reading.sqlite3'), timeout=15)\n        g.db.row_factory = sqlite3.Row\n        g.db.executescript(SCHEMA)\n    return g.db\n\n@app.teardown_appcontext\ndef close_db(error):\n    if 'db' in g:\n        g.db.close()\n\ndef digest(value):\n    return hashlib.sha256(value.encode()).hexdigest()\n\ndef write(sql, args):\n    db().execute(sql, args)\n    db().commit()\n\ndef rows(sql, args=()):\n    return [dict(r) for r in db().execute(sql, args)]\n\n@app.get('/')\ndef home():\n    return send_from_directory(ROOT, 'index.html')\n\n@app.get('/<file>')\ndef asset(file):\n    if file not in ('app.js', 'style.css', 'source.zip'):\n        abort(404)\n    if file == 'source.zip':\n        import io, zipfile\n        from flask import send_file\n        data = io.BytesIO()\n        with zipfile.ZipFile(data, 'w', zipfile.ZIP_DEFLATED) as archive:\n            for name in ('app.py','requirements.txt','.replit','books.json','schema.sql','index.html','app.js','style.css','README.md','worker.js'):\n                path = ROOT / name\n                if path.is_file():\n                    archive.write(path,name)\n        data.seek(0)\n        return send_file(data, as_attachment=True, download_name='marginalia-source.zip')\n    return send_from_directory(ROOT, file)\n\n@app.route('/api/<path:p>', methods=['GET','POST'])\ndef api(p):\n    post = request.method == 'POST'\n    if post and (not request.is_json or request.headers.get('Origin','').split('://')[-1] != request.host):\n        return jsonify(error='Invalid origin.'),403\n    body = request.get_json() if post else {}\n    if not isinstance(body,dict):\n        return jsonify(error='Invalid body.'),400\n    sid = digest(request.cookies.get('marginalia',''))\n    now = int(time.time())\n    users = rows('SELECT r.* FROM readers r JOIN sessions s ON s.reader=r.id WHERE s.id=? AND expires>?',(sid,now))\n    u = users[0] if users else {}\n    if p == 'catalog' and not post:\n        catalog = [dict(b) for b in BOOKS]\n        for e in rows('SELECT * FROM edits'):\n            catalog[e['book']].update(json.loads(e['body']))\n        return jsonify([b for b in catalog if b.get('published',True) or u.get('admin')])\n    if post and p in ('create','login'):\n        key = secrets.token_hex(32) if p=='create' else str(body.get('key','')).strip()\n        uid = digest(key)\n        if p == 'create':\n            write('INSERT INTO readers(id) VALUES(?)',(uid,))\n        elif not rows('SELECT id FROM readers WHERE id=?',(uid,)):\n            return jsonify(error='Unknown reading key.'),401\n        session = secrets.token_hex(32)\n        write('INSERT INTO sessions VALUES(?,?,?)',(digest(session),uid,now+2592000))\n        result = jsonify(key=key) if p=='create' else jsonify(ok=True)\n        result.set_cookie('marginalia',session,max_age=2592000,httponly=True,samesite='Strict',secure=request.is_secure or request.headers.get('X-Forwarded-Proto')=='https')\n        return result\n    if post and p=='logout':\n        write('DELETE FROM sessions WHERE id=?',(sid,))\n        result=jsonify(ok=True)\n        result.delete_cookie('marginalia')\n        return result\n    if p=='state' and not post:\n        progress = rows('SELECT book,idea,minutes FROM progress WHERE reader=?',(u.get('id'),))\n        return jsonify(account=bool(u),admin=bool(u.get('admin')),marks=rows('SELECT book,idea,saved,tried FROM marks WHERE reader=?',(u.get('id'),)),progress=next(iter(progress),None))\n    if not u or not post:\n        return jsonify(error='Sign in required.'),401\n    book,idea=body.get('book'),body.get('idea')\n    if type(book) is not int or not 0<=book<len(BOOKS):\n        return jsonify(error='Unknown guide.'),400\n    if p=='admin':\n        if not u['admin']:\n            return jsonify(error='Administrator required.'),403\n        fields=('title','author','overview','example','limit')\n        ideas=body.get('ideas')\n        if any(not isinstance(body.get(k),str) or not 0<len(body[k].strip())<=4000 for k in fields) or not isinstance(ideas,list) or len(ideas)!=len(BOOKS[book]['ideas']) or any(not isinstance(x,str) or not 0<len(x.strip())<=2000 for x in ideas):\n            return jsonify(error='Invalid guide fields.'),400\n        content={k:body[k] for k in fields}\n        content.update(ideas=ideas,published=body.get('published') is not False)\n        write('INSERT OR REPLACE INTO edits VALUES(?,?)',(book,json.dumps(content)))\n    elif type(idea) is not int or not 0<=idea<len(BOOKS[book]['ideas']):\n        return jsonify(error='Unknown idea.'),400\n    elif p=='progress' and body.get('minutes') in (2,5,15):\n        write('INSERT OR REPLACE INTO progress VALUES(?,?,?,?)',(u['id'],book,idea,body['minutes']))\n    elif p=='mark' and body.get('field') in ('saved','tried') and type(body.get('on')) is bool:\n        field=body['field']\n        write(f'INSERT INTO marks(reader,book,idea,{field}) VALUES(?,?,?,?) ON CONFLICT(reader,book,idea) DO UPDATE SET {field}=excluded.{field}',(u['id'],book,idea,int(body['on'])))\n    else:\n        return jsonify(error='Invalid action.'),400\n    return jsonify(ok=True)\n\n@app.after_request\ndef private(response):\n    if request.path.startswith('/api/'):\n        response.headers['Cache-Control']='no-store'\n    response.headers['X-Content-Type-Options']='nosniff'\n    return response\n\nif __name__ == '__main__':\n    app.run(host='0.0.0.0',port=int(os.environ.get('PORT','3000')))\n","schema.sql":"CREATE TABLE IF NOT EXISTS readers (id TEXT PRIMARY KEY, admin INTEGER NOT NULL DEFAULT 0);\nCREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, reader TEXT NOT NULL, expires INTEGER NOT NULL);\nCREATE TABLE IF NOT EXISTS marks (reader TEXT NOT NULL, book INTEGER NOT NULL, idea INTEGER NOT NULL, saved INTEGER NOT NULL DEFAULT 0, tried INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(reader,book,idea));\nCREATE TABLE IF NOT EXISTS progress (reader TEXT PRIMARY KEY, book INTEGER NOT NULL, idea INTEGER NOT NULL, minutes INTEGER NOT NULL);\nCREATE TABLE IF NOT EXISTS edits (book INTEGER PRIMARY KEY, body TEXT NOT NULL);","requirements.txt":"Flask>=3.1,<4\n",".replit":"run = \"pip install -r requirements.txt && python app.py\"\nmodules = [\"python-3.11\"]\n","README.md":"# Marginalia\nOpen the reading room, select a guide, and choose a reading mode. Browse as a guest or use My account to generate a private reading key. Save it for cross-device sign-in. Guest progress is copied when creating an account. The key is a bearer credential; keep it private. No email recovery is configured.\n\n## Replit or local\nInstall Python 3.11+ and pip install -r requirements.txt, then run python app.py. The .replit run command does both steps. The Flask edition stores data in reading.sqlite3; keep this file on a persistent disk. Set MARGINALIA_DB to change the path. Production and local libraries are separate.\n\n## Administrator\nCreate a reading account on your own deployment. Compute SHA-256 of your reading key locally (Python: import hashlib,getpass; print(hashlib.sha256(getpass.getpass().strip().encode()).hexdigest())). In your private D1 console or local SQLite administration tool, run UPDATE readers SET admin=1 WHERE id='YOUR_HASH'; refresh My account and select Edit guides. Never paste the reading key into the SQL console. No default admin password exists.\n\n## Hosted edition\nworker.js runs the same reading UI and API on Cloudflare Workers with the DB binding to a D1 database initialized with schema.sql. All source files are available from the download. The live packaging layer adds the downloadable archive. Topic guides mark unidentified editions. Where linked, library searches are catalog aids, not evidence reviews.\n"};
const TAIL="const BOOKS=JSON.parse(FILES[\"books.json\"]);const json=(x,status=200,h={})=>new Response(JSON.stringify(x),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store',...h}});\nconst digest=async s=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s))),n=>n.toString(16).padStart(2,'0')).join('');\nconst token=()=>crypto.randomUUID().replaceAll('-','')+crypto.randomUUID().replaceAll('-','');\nconst cookie=(s,age)=>'marginalia='+s+'; Path=/; Max-Age='+age+'; HttpOnly; Secure; SameSite=Strict';\nasync function api(req,env,p){\nconst db=env.DB, post=req.method==='POST',now=Math.floor(Date.now()/1000);\nif(post&&(req.headers.get('Origin')!==new URL(req.url).origin||!req.headers.get('Content-Type')?.startsWith('application/json')))return json({error:'Invalid request origin.'},403);\nconst body=post?await req.json():{},sid=(req.headers.get('Cookie')||'').match(/(?:^|; )marginalia=([a-f0-9]{64})(?:;|$)/)?.[1], hashed=sid?await digest(sid):'',user=hashed?await db.prepare('SELECT r.id,r.admin FROM readers r JOIN sessions s ON s.reader=r.id WHERE s.id=? AND s.expires>?').bind(hashed,now).first():null;\nif(p==='/api/catalog'&&!post){let result=BOOKS.map(b=>({...b}));for(const r of (await db.prepare('SELECT * FROM edits').all()).results)Object.assign(result[r.book],JSON.parse(r.body));return json(result.filter(b=>b.published!==false||user?.admin))}\nif(post&&(p==='/api/create'||p==='/api/login')){let key=p.endsWith('create')?token():String(body.key||'').trim();if(!/^[0-9a-f]{64}$/.test(key))return json({error:'Check your reading key.'},401);let id=await digest(key);if(p.endsWith('create'))await db.prepare('INSERT INTO readers(id) VALUES(?)').bind(id).run();else if(!await db.prepare('SELECT id FROM readers WHERE id=?').bind(id).first())return json({error:'Unknown reading key.'},401);let s=token();await db.prepare('INSERT INTO sessions VALUES(?,?,?)').bind(await digest(s),id,now+2592000).run();return json(p.endsWith('create')?{key}:{ok:true},200,{'Set-Cookie':cookie(s,2592000)})}\nif(p==='/api/logout'&&post){if(hashed)await db.prepare('DELETE FROM sessions WHERE id=?').bind(hashed).run();return json({},200,{'Set-Cookie':cookie('',0)})}\nif(p==='/api/state'&&!post){if(!user)return json({account:false,marks:[],progress:null});return json({account:true,admin:!!user.admin,marks:(await db.prepare('SELECT book,idea,saved,tried FROM marks WHERE reader=?').bind(user.id).all()).results,progress:await db.prepare('SELECT book,idea,minutes FROM progress WHERE reader=?').bind(user.id).first()})}\nif(!user||!post)return json({error:'Sign in to continue.'},401);\nconst {book,idea,minutes,field,on}=body;if(!Number.isInteger(book)||!BOOKS[book])return json({error:'Unknown guide.'},400);\nif(p==='/api/admin'){if(!user.admin)return json({error:'Administrator access required.'},403);let edit={};for(const k of ['title','author','overview','example','limit']){if(typeof body[k]!=='string'||!body[k].trim()||body[k].length>4000)return json({error:'Check the guide fields.'},400);edit[k]=body[k].trim()}if(!Array.isArray(body.ideas)||body.ideas.length!==BOOKS[book].ideas.length||body.ideas.some(x=>typeof x!=='string'||!x.trim()||x.length>2000))return json({error:'Keep one takeaway on each line.'},400);edit.ideas=body.ideas;edit.published=body.published!==false;await db.prepare('INSERT OR REPLACE INTO edits VALUES(?,?)').bind(book,JSON.stringify(edit)).run();return json({ok:true})}\nif(!Number.isInteger(idea)||idea<0||idea>=BOOKS[book].ideas.length)return json({error:'Unknown idea.'},400);\nif(p==='/api/progress'&&[2,5,15].includes(minutes)){await db.prepare('INSERT OR REPLACE INTO progress VALUES(?,?,?,?)').bind(user.id,book,idea,minutes).run();return json({ok:true})}\nif(p==='/api/mark'&&['saved','tried'].includes(field)&&typeof on==='boolean'){await db.prepare('INSERT INTO marks(reader,book,idea,'+field+') VALUES(?,?,?,?) ON CONFLICT(reader,book,idea) DO UPDATE SET '+field+'=excluded.'+field).bind(user.id,book,idea,+on).run();return json({ok:true})}return json({error:'Invalid operation.'},400)}\n\nfunction zip(files){const out=[],entries=[],enc=new TextEncoder();function put(v,n){for(let j=0;j<n;j++){out.push(v&255);v>>>=8}}function append(a){for(let k of a)out.push(k)}for(const [name,value] of Object.entries(files)){const data=enc.encode(value),n=enc.encode(name),pos=out.length;let crc=0xffffffff;for(let v of data){crc^=v;for(let j=0;j<8;j++)crc=(crc>>>1)^((crc&1)?0xedb88320:0)}crc=(~crc)>>>0;put(0x04034b50,4);put(20,2);put(0,2);put(0,2);put(0,2);put(33,2);put(crc,4);put(data.length,4);put(data.length,4);put(n.length,2);put(0,2);append(n);append(data);entries.push({n,data,crc,pos})}const start=out.length;for(const {n,data,crc,pos} of entries){put(0x02014b50,4);put(20,2);put(20,2);put(0,2);put(0,2);put(0,2);put(33,2);put(crc,4);put(data.length,4);put(data.length,4);put(n.length,2);for(let i=0;i<4;i++)put(0,2);put(0,4);put(pos,4);append(n)}let size=out.length-start;put(0x06054b50,4);put(0,2);put(0,2);put(entries.length,2);put(entries.length,2);put(size,4);put(start,4);put(0,2);return new Uint8Array(out)}\nexport default {async fetch(req,env){try{const p=new URL(req.url).pathname;if(p.startsWith('/api/')) return await api(req,env,p);if(req.method!=='GET'&&req.method!=='HEAD')return new Response('Method not allowed',{status:405});if(p==='/source.zip'){const src='const FILES='+JSON.stringify(FILES)+';\\nconst TAIL='+JSON.stringify(TAIL)+';\\n'+TAIL;return new Response(zip({...FILES,'worker.js':src}),{headers:{'Content-Type':'application/zip','Content-Disposition':'attachment; filename=marginalia-source.zip'}})}const map={'/':['index.html','text/html; charset=utf-8'],'/app.js':['app.js','text/javascript; charset=utf-8'],'/style.css':['style.css','text/css; charset=utf-8']};if(!Object.hasOwn(map,p))return new Response('Not found',{status:404});const [file,type]=map[p];return new Response(FILES[file],{headers:{'Content-Type':type,'X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer','Content-Security-Policy':\"default-src 'self'; style-src 'self' 'unsafe-inline'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'\"}})}catch{return json({error:'Could not process the request.'},400)}}}";
